-- Daily range partitions (15.5, 8.8, 25.9) ---------------------------------------------------------------------
-- The scheduler calls bastion_ensure_partitions() daily; it creates partitions `days_ahead` days out.
CREATE OR REPLACE FUNCTION bastion_ensure_partitions(parent regclass, days_ahead integer)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  d date;
  part_name text;
BEGIN
  FOR d IN SELECT generate_series(current_date, current_date + days_ahead, interval '1 day')::date LOOP
    part_name := format('%s_%s', parent::text, to_char(d, 'YYYYMMDD'));
    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS %I PARTITION OF %s FOR VALUES FROM (%L) TO (%L)',
      part_name, parent, d::timestamptz, (d + 1)::timestamptz);
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION bastion_drop_partitions_before(parent regclass, cutoff date)
RETURNS integer LANGUAGE plpgsql AS $$
DECLARE
  child record;
  dropped integer := 0;
  suffix text;
BEGIN
  FOR child IN
    SELECT c.relname FROM pg_inherits i JOIN pg_class c ON c.oid = i.inhrelid WHERE i.inhparent = parent
  LOOP
    suffix := right(child.relname, 8);
    IF suffix ~ '^[0-9]{8}$' AND to_date(suffix, 'YYYYMMDD') < cutoff THEN
      EXECUTE format('DROP TABLE %I', child.relname);
      dropped := dropped + 1;
    END IF;
  END LOOP;
  RETURN dropped;
END $$;

SELECT bastion_ensure_partitions('call_log', 7);
SELECT bastion_ensure_partitions('egress_events', 7);
SELECT bastion_ensure_partitions('distribution_events', 7);

